import * as THREE from 'three';
import { OBJExporter } from 'three/examples/jsm/exporters/OBJExporter.js';
import * as BufferGeometryUtils from 'three/examples/jsm/utils/BufferGeometryUtils.js';
import fs from 'fs';
import path from 'path';
import { createScene } from './data/object.js';

// Setup global THREE if needed by some loaders/exporters (though usually not for pure JSM)
// global.THREE = THREE; 

const OUTPUT_DIR_PARTS = '/root/output/part_meshes';
const OUTPUT_DIR_LINKS = '/root/output/links';

function ensureDir(dirPath) {
    if (!fs.existsSync(dirPath)) {
        fs.mkdirSync(dirPath, { recursive: true });
    }
}

function buildPartMap(root) {
    const parts = new Map();

    // 1. Register all named groups as potential parts
    root.traverse((obj) => {
        if (obj.isGroup && obj.name) {
            parts.set(obj.name, { group: obj, meshes: [] });
        }
    });

    // 2. Assign meshes to nearest named ancestor
    root.traverse((obj) => {
        if (!obj.isMesh) return;

        let parent = obj.parent;
        // Traverse up until we find a parent that is a registered named group
        while (parent && !(parent.isGroup && parent.name && parts.has(parent.name))) {
            parent = parent.parent;
        }

        if (parent) {
            parts.get(parent.name).meshes.push(obj);
        } else {
            console.warn(`Mesh ${obj.name} has no named Group ancestor!`);
        }
    });

    // 3. Filter out parts with no meshes and return
    return Array.from(parts.entries())
        .filter(([name, data]) => data.meshes.length > 0)
        .map(([name, data]) => ({ name, ...data }));
}

function bakeTransformToGeometry(mesh) {
    const geom = mesh.geometry.clone();
    geom.applyMatrix4(mesh.matrixWorld);

    // Ensure consistency for merging
    if (geom.index) {
        // toNonIndexed is safer for merging usually, or we ensure all have indices.
        // But mergeGeometries handles mixed if we are careful? 
        // Actually mergeGeometries often prefers indexed or non-indexed consistency.
        // Let's standardise to non-indexed for safety if indices are missing in some.
        // However, usually it's better to keep it if possible. 
        // The skill says: "if (geom.index) geom = geom.toNonIndexed();"
        // Let's follow the skill recommendation to avoid issues.
        // But wait, toNonIndexed() explodes vertices count.
        // Let's try to keep it optimized first, but if it fails, we know why.
        // Skill said: "if (geom.index) geom = geom.toNonIndexed();"
        // This is a strong suggestion.
        // However, OBJ export size might be huge.
        // Let's check `BufferGeometryUtils.mergeGeometries`.
        // It requires attributes to match.
    }

    // Skill advice:
    // if (geom.index) geom = geom.toNonIndexed();
    // if (!geom.attributes.normal) geom.computeVertexNormals();

    // Let's implement robust baking
    // If we want to merge, usually we strip indices or generate them for all.
    // Let's go with non-indexed as per skill for simplicity and compatibility.
    // (Although it might make files larger)

    // Actually, let's just ensure normals exist.
    if (!geom.attributes.normal) {
        geom.computeVertexNormals();
    }

    return geom;
}

function exportParts() {
    console.log("Initializing scene...");
    const root = createScene();

    // CRITICAL: Update world matrices before doing anything
    root.updateMatrixWorld(true);

    console.log("Partitioning parts...");
    const parts = buildPartMap(root);
    console.log(`Found ${parts.length} parts.`);

    const exporter = new OBJExporter();

    ensureDir(OUTPUT_DIR_PARTS);
    ensureDir(OUTPUT_DIR_LINKS);

    parts.forEach(part => {
        console.log(`Processing part: ${part.name} (${part.meshes.length} meshes)`);

        const partMeshDir = path.join(OUTPUT_DIR_PARTS, part.name);
        ensureDir(partMeshDir);

        const bakedGeometries = [];

        part.meshes.forEach(mesh => {
            // 1. Export individual mesh
            const meshName = mesh.name || 'unnamed_mesh';
            const individualGeom = bakeTransformToGeometry(mesh);

            const tempMesh = new THREE.Mesh(individualGeom);
            tempMesh.name = meshName;

            const objData = exporter.parse(tempMesh);
            fs.writeFileSync(path.join(partMeshDir, `${meshName}.obj`), objData);

            bakedGeometries.push(individualGeom);
        });

        // 2. Merge and export link mesh
        if (bakedGeometries.length > 0) {
            // Ensure all geometries are compatible for merge
            // We'll convert all to non-indexed to be safe for merging as per skill hint
            // or just try merging.
            // Skill hint: "if (geom.index) geom = geom.toNonIndexed();"

            const compatibleGeoms = bakedGeometries.map(g => {
                let geom = g;
                if (geom.index) geom = geom.toNonIndexed();
                return geom;
            });

            // Clean up attributes that might not match (like uv, color if some have and others don't)
            // For OBJ structure, we mainly care about position and normal.
            // Let's traverse and remove 'uv' if not present in all? 
            // BufferGeometryUtils.mergeGeometries handles this by taking the intersection of attributes usually?
            // No, it usually fails if attributes don't match.
            // Let's just keep position and normal.

            compatibleGeoms.forEach(g => {
                for (const name in g.attributes) {
                    if (name !== 'position' && name !== 'normal') {
                        g.deleteAttribute(name);
                    }
                }
            });

            try {
                const mergedGeom = BufferGeometryUtils.mergeGeometries(compatibleGeoms, false);
                const mergedMesh = new THREE.Mesh(mergedGeom);
                mergedMesh.name = part.name;

                const linkObjData = exporter.parse(mergedMesh);
                fs.writeFileSync(path.join(OUTPUT_DIR_LINKS, `${part.name}.obj`), linkObjData);
            } catch (err) {
                console.error(`Failed to merge meshes for part ${part.name}:`, err);
            }
        }
    });

    console.log("Export complete.");
}

exportParts();

