    // Let's go with non-indexed as per skill for simplicity and compatibility.
    // (Although it might make files larger)

    // Actually, let's just ensure normals exist.
    if (!geom.attributes.normal) {
        geom.computeVertexNormals();
    }

    return geom;
}

function exportParts() {
    console.log("Initializing scene...");
    const root = createScene();

    // CRITICAL: Update world matrices before doing anything
    root.updateMatrixWorld(true);

    console.log("Partitioning parts...");
    const parts = buildPartMap(root);
    console.log(`Found ${parts.length} parts.`);

    const exporter = new OBJExporter();

    ensureDir(OUTPUT_DIR_PARTS);
    ensureDir(OUTPUT_DIR_LINKS);

    parts.forEach(part => {
        console.log(`Processing part: ${part.name} (${part.meshes.length} meshes)`);

        const partMeshDir = path.join(OUTPUT_DIR_PARTS, part.name);
        ensureDir(partMeshDir);

        const bakedGeometries = [];

        part.meshes.forEach(mesh => {
            // 1. Export individual mesh
            const meshName = mesh.name || 'unnamed_mesh';
            const individualGeom = bakeTransformToGeometry(mesh);

            const tempMesh = new THREE.Mesh(individualGeom);
            tempMesh.name = meshName;

            const objData = exporter.parse(tempMesh);
            fs.writeFileSync(path.join(partMeshDir, `${meshName}.obj`), objData);

            bakedGeometries.push(individualGeom);
        });

        // 2. Merge and export link mesh
        if (bakedGeometries.length > 0) {
            // Ensure all geometries are compatible for merge
            // We'll convert all to non-indexed to be safe for merging as per skill hint
            // or just try merging.
            // Skill hint: "if (geom.index) geom = geom.toNonIndexed();"

            const compatibleGeoms = bakedGeometries.map(g => {
                let geom = g;
                if (geom.index) geom = geom.toNonIndexed();
                return geom;
            });

            // Clean up attributes that might not match (like uv, color if some have and others don't)
            // For OBJ structure, we mainly care about position and normal.
            // Let's traverse and remove 'uv' if not present in all? 
            // BufferGeometryUtils.mergeGeometries handles this by taking the intersection of attributes usually?
            // No, it usually fails if attributes don't match.
            // Let's just keep position and normal.

            compatibleGeoms.forEach(g => {
                for (const name in g.attributes) {
                    if (name !== 'position' && name !== 'normal') {
                        g.deleteAttribute(name);
                    }
                }
            });

            try {
                const mergedGeom = BufferGeometryUtils.mergeGeometries(compatibleGeoms, false);
                const mergedMesh = new THREE.Mesh(mergedGeom);
                mergedMesh.name = part.name;

                const linkObjData = exporter.parse(mergedMesh);
                fs.writeFileSync(path.join(OUTPUT_DIR_LINKS, `${part.name}.obj`), linkObjData);
            } catch (err) {
                console.error(`Failed to merge meshes for part ${part.name}:`, err);
            }
        }
    });

    console.log("Export complete.");
}

exportParts();
